head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.vScrenID = "ULDBNS10300.xml";
scwin.vRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_Search
 * 설명       : 발행기관을 조회한다.
 ***********************************************/
scwin.fn_Search = function() {
    var param = '';
    param += "&{P}V_LIST_STAT_CD=" + $c.stf.getObjectValue(cmb_ListStatCd);
    param += "&{P}V_EXP_YY=" + $c.stf.getObjectValue(cmb_ExpYy);
    param += "&{P}V_ISU_NM=" + $c.stf.getObjectValue(txb_IsuNm);
    var dsNm = 'BNS_STRIP_STAT';
    var qryId = 'lds.stf.bnschg.select.listStripStat';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 함수명   : fn_GetParListBndIsu
 * 설명       : 상장종목 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParListBndIsu = function(arrPar) {
    arrPar[0] = {
        LIST_TYPE_CD: '2'
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParListBndIsu
 * 설명       : 상장종목 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParListBndIsu = function(arrPar) {
    $c.stf.setObjectValue(txb_IsuNm, arrPar[0].STD_CD);
};


/********************************************** 
 * 함수명   : fn_GetParStripSplitDtl
 * 설명       : 스트립분리내역 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParStripSplitDtl = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_List.getCellData(dts_List.getRowPosition(), 'STD_CD')
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
1;
scwin.gform_onload = function() {
    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Search);
    //목록조회
    scwin.fn_Search();
};
scwin.bnt_Select_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    var fileNm = $c.ut.cGetToday("yyyymmdd") + '_' + '스트립현황조회';
    $c.data.downloadGridViewExcel(grd_List, "스트립현황조회", "", 8);
};
scwin.img_IsuNm_onclick = function() {
    scwin.fn_GetPar = fn_GetParListBndIsu;
    scwin.fn_SetPar = fn_SetParListBndIsu;
    $c.bns.fn_PopListBndIsuSearch(img_IsuNm);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    txb_TotalCnt.setValue("총 " + rowcount + "건");
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.grd_List_OnClick = function(row, colid) {
    if (row == 0) return;
    if (colid == 'STD_CD') {
        scwin.fn_GetPar = fn_GetParStripSplitDtl;
        $c.bns.fn_PopStripSplitDtlSearch(grd_List);
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
